SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY customer_id), 4) AS amount_share, SUM(discount) OVER (PARTITION BY customer_id ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount, LAST_VALUE(channel, TRUE) OVER (PARTITION BY channel ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, CORR(discount, shipping_fee) OVER (PARTITION BY channel) AS corr_discount_shipping_fee FROM orders;
